#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> subset_sums_first, subset_sums_second;
    int half = n / 2;

    function<void(int, int)> compute_first_half = [&](int index, int total) {
        if (index == half) {
            subset_sums_first.push_back(total);
        } else {
            compute_first_half(index + 1, (total + a[index]) % m);
            compute_first_half(index + 1, total);
        }
    };

    function<void(int, int)> compute_second_half = [&](int index, int total) {
        if (index == n) {
            subset_sums_second.push_back(total);
        } else {
            compute_second_half(index + 1, (total + a[index]) % m);
            compute_second_half(index + 1, total);
        }
    };

    compute_first_half(0, 0);
    compute_second_half(half, 0);

    set<int> unique_first_set(subset_sums_first.begin(), subset_sums_first.end());
    vector<int> unique_first(unique_first_set.begin(), unique_first_set.end());
    int max_sum = 0;

    for (int val : subset_sums_second) {
        int target = m - val;
        auto it = lower_bound(unique_first.begin(), unique_first.end(), target);
        if (it != unique_first.begin()) {
            --it;
            int candidate = *it + val;
            if (candidate > max_sum) {
                max_sum = candidate;
            }
        }
    }

    cout << max_sum << "\n";

    return 0;
}
